class Solution {
    private boolean isPrime(int value){
        if(value<2)return false;
        for(int divisor=2;divisor*divisor<=value;divisor++)if(value%divisor==0)return false;
        return true;
    }
    public int maximumPrimeDifference(int[] nums){
        int first=-1,last=-1;
        for(int index=0;index<nums.length;index++)if(isPrime(nums[index])){
            if(first<0)first=index;
            last=index;
        }
        return last-first;
    }
}

code.kotlin:
class Solution {
    private fun isPrime(value:Int):Boolean{
        if(value<2)return false;
        var divisor=2;
        while(divisor*divisor<=value){
            if(value%divisor==0)return false;
            divisor++
        };
        return true
    }
    fun maximumPrimeDifference(nums:IntArray):Int{
        var first=-1;
        var last=-1;
        for(index in nums.indices)if(isPrime(nums[index])){
            if(first<0)first=index;
            last=index
        };
        return last-first
    }
}

